/**
 * The `zotero_browse` tool: library discovery without assuming structure.
 * Model-facing bounded listing for libraries, collections, saved searches, tags, itemTypes.
 * All library resolution follows canonical SupportedLocalLibrary identity.
 * @module dsh-zotero/tools/browse
 */

import type { Context } from '@deepseek-ai/cordis'
import type { ContentBlock } from '@deepseek-ai/dsh-llm'
import {
  type InferArgs,
  type InferValue,
  type ToolResult,
  type ToolResultView,
} from '@deepseek-ai/dsh-tools'
import { defineZoteroTool as defineTool } from '../define-tool.js'
import { boundedPresentationMeta, projectBrowseMeta } from '../presentation-meta.js'
import { identityToolWrapper, type ToolWrapper } from '../result-delivery.js'
import { metaRecordOf } from './present.js'
import { browseRowOf, BROWSE_KINDS, type BrowseRow } from '../browse-rows.js'
import { assertPublicationsSupported } from '../refs.js'
import { isItemTypeIdentifier } from '../ref-grammar.js'
import { assertIntInRange, assertNonBlank, LIBRARY_SCHEMA, parseLibrary } from './validate.js'
import {
  ITEM_FIELDS_ITEM_TYPE_MESSAGE,
  ITEM_TYPE_SCOPE_MESSAGE,
  MATCH_REQUIRES_Q_MESSAGE,
  PARENT_REF_SCOPE_MESSAGE,
  Q_MATCH_SCOPE_MESSAGE,
  invalidArgs,
  libraryNotAllowedMessage,
} from '../errors.js'
import type { ZoteroService } from '../service.js'
import type { ZoteroBrowseKind, ZoteroBrowseRequest } from '../types.js'

const BROWSE_PARAMETERS = {
  kind: {
    type: 'string',
    enum: [...BROWSE_KINDS],
    required: true,
    description:
      'Browse libraries, collections, savedSearches, tags, itemTypes, itemFields (itemType required).',
  },
  library: {
    ...LIBRARY_SCHEMA,
    default: { type: 'user', id: 0 },
    description:
      'For collections/savedSearches/tags; defaults user/0. Invalid for libraries/itemTypes/itemFields.',
  },
  parentRef: {
    type: 'string',
    description: 'Collections only: parent collection ref; omit for top-level collections.',
  },
  tagScope: {
    type: 'string',
    enum: ['library', 'collection', 'publications'],
    description: 'Tags only: count scope (library, collection, or publications).',
  },
  tagCollection: {
    type: 'string',
    description: 'Tags with collection scope: collection ref or exact name.',
  },
  itemLevel: {
    type: 'string',
    enum: ['top', 'all'],
    default: 'top',
    description: 'Tags only: top-level (default) or all items including children.',
  },
  itemQuery: {
    type: 'string',
    description: 'Tags only: count tags on matching items.',
  },
  itemQueryMode: {
    type: 'string',
    enum: ['titleCreatorYear', 'everything'],
    default: 'titleCreatorYear',
    description: 'itemQuery mode: titleCreatorYear (default) or everything.',
  },
  itemType: {
    type: 'string',
    description: 'itemFields only: Zotero item type, e.g. dataset.',
  },
  q: {
    type: 'string',
    description: 'Substring filter; tags only.',
  },
  match: {
    type: 'string',
    enum: ['contains', 'startsWith'],
    default: 'contains',
    description: 'Tag q match: contains (default) or startsWith.',
  },
  offset: { type: 'integer', default: 0, description: 'Offset.' },
  limit: {
    type: 'integer',
    default: 20,
    description: '1..maxBrowseResults; over-cap values are refused.',
  },
} as const

type BrowseArgs = InferArgs<typeof BROWSE_PARAMETERS>

const BROWSE_OUTPUT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    kind: { type: 'string', required: true },
    library: {
      type: 'object',
      additionalProperties: false,
      properties: {
        type: { type: 'string', required: true },
        id: { type: 'integer', required: true },
      },
    },
    serverId: { type: 'string' },
    // Each kind lists its own row shape, so the model can rely on
    // collections carrying path/depth/parentRef, tags carrying count, and
    // saved searches carrying conditions straight from the schema.
    items: {
      type: 'array',
      required: true,
      items: {
        oneOf: [
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              library: {
                ...LIBRARY_SCHEMA,
                required: true,
              },
              name: { type: 'string', required: true },
            },
          },
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              ref: { type: 'string', required: true },
              name: { type: 'string', required: true },
              parentRef: { type: 'string' },
              path: { type: 'array', required: true, items: { type: 'string' } },
              depth: { type: 'integer', required: true },
              childCount: { type: 'integer' },
              itemCount: { type: 'integer' },
            },
          },
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              ref: { type: 'string', required: true },
              name: { type: 'string', required: true },
              // The browse domain normalizes (and refuses malformed) rows, so
              // the model sees the closed condition record.
              conditions: {
                type: 'array',
                items: {
                  type: 'object',
                  additionalProperties: false,
                  properties: {
                    condition: { type: 'string', required: true },
                    operator: { type: 'string', required: true },
                    value: { type: 'string', required: true },
                  },
                },
              },
            },
          },
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              tag: { type: 'string', required: true },
              count: { type: 'integer' },
            },
          },
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              itemType: { type: 'string', required: true },
              localized: { type: 'string' },
            },
          },
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              field: { type: 'string', required: true },
              localized: { type: 'string' },
            },
          },
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              creatorType: { type: 'string', required: true },
              localized: { type: 'string' },
            },
          },
        ],
      },
    },
    total: { type: 'integer', required: true },
    offset: { type: 'integer', required: true },
    returned: { type: 'integer', required: true },
    libraryVersion: { type: 'integer' },
    nextOffset: { type: 'integer' },
    maximum: { type: 'integer' },
  },
} as const

type BrowseOutput = InferValue<typeof BROWSE_OUTPUT_SCHEMA>

/**
 * The tag-facet messages are this layer's own wording: they name the
 * model-facing arguments (`tagScope`), while the domain's counterpart names
 * the request field it validates (`SCOPE_FACET_KIND_MESSAGE`, `scope`).
 */
export const TAG_FACET_SCOPE_MESSAGE =
  'tagScope/itemLevel/itemQuery are only valid when kind="tags"'
export const TAG_COLLECTION_SCOPE_MESSAGE = 'tagCollection requires tagScope="collection"'
export const TAG_SCOPE_COLLECTION_MESSAGE =
  'tagScope="collection" requires tagCollection (a zotero:// ref or a collection name)'
export const ITEM_LEVEL_SCOPE_MESSAGE =
  'itemLevel/itemQuery require tagScope (library, collection, or publications)'
export const ITEM_QUERY_MODE_MESSAGE = 'itemQueryMode requires itemQuery'

function buildRequest(args: BrowseArgs, config: { maxBrowseResults: number }): ZoteroBrowseRequest {
  const kind = args.kind as ZoteroBrowseKind
  const offset = args.offset ?? 0
  const limit = args.limit ?? 20
  assertIntInRange('offset', offset, 0, 1_000_000)
  if (!Number.isInteger(limit) || limit < 1 || limit > config.maxBrowseResults) {
    invalidArgs(
      `limit must be an integer between 1 and ${config.maxBrowseResults}; got ${limit}. Set limit <= ${config.maxBrowseResults} and use offset for the next page.`,
    )
  }
  const library = parseLibrary(args.library)
  // Fail-closed: libraries/itemTypes/itemFields are global; library param is not allowed
  if (
    (kind === 'libraries' || kind === 'itemTypes' || kind === 'itemFields') &&
    library !== undefined
  ) {
    invalidArgs(libraryNotAllowedMessage(kind))
  }
  const itemType = args.itemType
  if (itemType !== undefined && kind !== 'itemFields') {
    invalidArgs(ITEM_TYPE_SCOPE_MESSAGE)
  }
  if (kind === 'itemFields') {
    if (itemType === undefined || !isItemTypeIdentifier(itemType)) {
      invalidArgs(ITEM_FIELDS_ITEM_TYPE_MESSAGE)
    }
  }
  const q = args.q
  const match = args.match
  if ((q !== undefined || match !== undefined) && kind !== 'tags') {
    invalidArgs(Q_MATCH_SCOPE_MESSAGE)
  }
  if (match !== undefined && q === undefined) {
    invalidArgs(MATCH_REQUIRES_Q_MESSAGE)
  }
  const query = q === undefined ? undefined : assertNonBlank('q', q)
  const parentRef = args.parentRef
  if (parentRef !== undefined && kind !== 'collections') {
    invalidArgs(PARENT_REF_SCOPE_MESSAGE)
  }
  const tagScope = args.tagScope
  const tagCollection = args.tagCollection
  const itemLevel = args.itemLevel
  const itemQuery = args.itemQuery
  const itemQueryMode = args.itemQueryMode
  if (
    (tagScope !== undefined ||
      itemLevel !== undefined ||
      itemQuery !== undefined ||
      itemQueryMode !== undefined) &&
    kind !== 'tags'
  ) {
    invalidArgs(TAG_FACET_SCOPE_MESSAGE)
  }
  if (tagCollection !== undefined && tagScope !== 'collection') {
    invalidArgs(TAG_COLLECTION_SCOPE_MESSAGE)
  }
  if (tagScope === 'collection' && tagCollection === undefined) {
    invalidArgs(TAG_SCOPE_COLLECTION_MESSAGE)
  }
  if (tagScope === 'publications') {
    assertPublicationsSupported(library)
  }
  const collection =
    tagCollection === undefined ? undefined : assertNonBlank('tagCollection', tagCollection)
  if ((itemLevel !== undefined || itemQuery !== undefined) && tagScope === undefined) {
    invalidArgs(ITEM_LEVEL_SCOPE_MESSAGE)
  }
  if (itemQueryMode !== undefined && itemQuery === undefined) {
    invalidArgs(ITEM_QUERY_MODE_MESSAGE)
  }
  const facetedQuery = itemQuery === undefined ? undefined : assertNonBlank('itemQuery', itemQuery)
  const scope =
    tagScope === undefined
      ? undefined
      : tagScope === 'collection'
        ? // The guards above refuse a collection scope without tagCollection,
          // so the narrowed value is the one the scope names.
          collection === undefined
          ? undefined
          : { kind: 'collection' as const, refOrName: collection }
        : { kind: tagScope as 'library' | 'publications' }
  return {
    kind,
    ...(library ? { library } : {}),
    ...(parentRef !== undefined ? { parentRef } : {}),
    ...(scope !== undefined ? { scope } : {}),
    ...(itemLevel !== undefined ? { itemLevel } : {}),
    ...(facetedQuery !== undefined ? { itemQuery: facetedQuery } : {}),
    ...(itemQueryMode !== undefined ? { itemQueryMode } : {}),
    ...(itemType !== undefined ? { itemType } : {}),
    ...(query !== undefined ? { q: query } : {}),
    ...(match !== undefined ? { match } : {}),
    offset,
    limit,
  }
}

/** The page announcement: the offset the next call should pass. */
export function browseMoreMessage(nextOffset: number): string {
  return `More: browse again with offset ${nextOffset}`
}

/** One rendered row line, plus the continuation line only libraries need. */
function browseRowLines(index: number, row: BrowseRow): string[] {
  const n = index + 1
  switch (row.kind) {
    case 'unknown':
      return [`${n}. Unrecognized browse row: ${row.raw}`]
    case 'library':
      return [`${n}. ${row.name} — ${row.libraryId}`, `   library=${row.libraryId}`]
    case 'collection': {
      // The full breadcrumb is the useful line, not just the leaf name.
      const breadcrumb = row.breadcrumb.join(' / ')
      return [`${n}. ${breadcrumb}${row.ref === '' ? '' : ` — ${row.ref}`}`]
    }
    case 'savedSearch':
      return [
        `${n}. ${row.name}${row.conditionCount === null ? '' : ` — ${row.conditionCount} conditions`}${
          row.ref === '' ? '' : ` — ${row.ref}`
        }`,
      ]
    case 'tag':
      return [`${n}. ${row.tag}${row.count === null ? '' : ` — ${row.count} items`}`]
    case 'itemType':
      return [`${n}. ${row.itemType}${row.localized === null ? '' : ` (${row.localized})`}`]
    case 'field':
      return [`${n}. field ${row.field}${row.localized === null ? '' : ` (${row.localized})`}`]
    case 'creatorType':
      return [
        `${n}. creatorType ${row.creatorType}${row.localized === null ? '' : ` (${row.localized})`}`,
      ]
  }
}

/**
 * The browse listing the model reads. The header states the page and the
 * total, each row follows `browseRowOf`'s classification, and a further page
 * closes with the offset to pass back. Row wording is this function's own;
 * which row is which is `browse-rows.ts`'s, shared with the Chat card.
 */
export function renderBrowse(_args: BrowseArgs, value: BrowseOutput): ContentBlock[] {
  const lines = [`${value.kind}: ${value.returned} of ${value.total}`]
  const items = value.items as readonly unknown[]
  items.forEach((item, index) => {
    lines.push(...browseRowLines(index, browseRowOf(item)))
  })
  if (value.nextOffset !== undefined) lines.push(browseMoreMessage(value.nextOffset))
  return [{ type: 'text', text: lines.join('\n') }]
}

/**
 * The completed browse card: the browsed kind plus the page facts. `meta`
 * is absent on nested code dispatch or malformed replay records, and a failed
 * call keeps the raw error content; both fall back to the generic card.
 */
function presentBrowseResult(_args: BrowseArgs, result: ToolResult): ToolResultView | undefined {
  const record = metaRecordOf(result)
  if (record === undefined) return undefined
  if (typeof record.kind !== 'string' || record.kind === '') return undefined
  if (typeof record.returned !== 'number' || typeof record.total !== 'number') return undefined
  return {
    card: 'generic',
    title: `Zotero browse: ${record.kind} (${record.returned} of ${record.total})`,
  }
}

export function registerBrowseTool(
  ctx: Context,
  service: ZoteroService,
  wrap: ToolWrapper = identityToolWrapper,
): void {
  ctx.tools.register(
    wrap(
      defineTool({
        name: 'zotero_browse',
        description: [
          'Browse Zotero library structure. Use libraries to discover personal/group libraries,',
          'collections/savedSearches/tags per library, itemTypes globally, itemFields with an itemType for its valid fields/creator types.',
          'Collections navigate the tree: omit parentRef for top-level, pass a collection ref to list its children.',
          'Tags accept a scope plus itemQuery for faceted discovery (which tags do my search hits carry?).',
          'Always offset/limit paginated; use for discovery before search/get.',
        ].join(' '),
        parameters: BROWSE_PARAMETERS,
        output: {
          schema: BROWSE_OUTPUT_SCHEMA,
          render: renderBrowse,
          presentationMeta: (_args, value) =>
            boundedPresentationMeta(projectBrowseMeta(value), ['items']),
        },
        presentCall: (args) => ({
          card: 'generic',
          kind: 'search',
          title: `Browse Zotero ${args.kind}`,
          rawInput: args.kind,
        }),
        presentResult: presentBrowseResult,
        isConcurrencySafe: () => true,
        async execute(args, exec) {
          const request = buildRequest(args, service.config)
          const value = await service.browse(request, exec.signal)
          return { ...value, maximum: service.config.maxBrowseResults }
        },
      }),
    ),
  )
}
